insert into public.terms (id, term, definition, subtopic_id, citation, outline_version, status) values
  ('t-real-property', 'Real property', 'Land, everything permanently attached to it, and the bundle of legal rights that come with owning it.', 'N1.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-personal-property', 'Personal property', 'Movable items not permanently attached to land. Also called chattels or personalty.', 'N1.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-fixture', 'Fixture', 'An item that was personal property but is now attached to real property so that it is treated as part of the real estate.', 'N1.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-trade-fixture', 'Trade fixture', 'Equipment a commercial tenant attaches for business use. It stays the tenant''s personal property and may be removed before the lease ends.', 'N1.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-emblements', 'Emblements', 'Annual crops produced by a tenant''s labor. They are personal property, and the tenant may return to harvest them if the tenancy ends early through no fault of their own.', 'N1.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-bundle-of-rights', 'Bundle of rights', 'The rights of an owner: possession, control, enjoyment, exclusion, and disposition.', 'N1.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-severance', 'Severance', 'Detaching something from the land, which turns real property into personal property, such as cutting standing timber.', 'N1.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-annexation', 'Annexation', 'Attaching personal property to land so that it becomes real property.', 'N1.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-bill-of-sale', 'Bill of sale', 'The written document used to transfer ownership of personal property.', 'N1.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-legal-description', 'Legal description', 'A description that identifies a parcel precisely enough that a surveyor could locate it. A street address is not enough.', 'N1.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-metes-and-bounds', 'Metes and bounds', 'A legal description that follows a parcel''s boundaries by distance and direction, starting and ending at the point of beginning.', 'N1.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-point-of-beginning', 'Point of beginning', 'The fixed starting point of a metes and bounds description. The description must return to it to close the parcel.', 'N1.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-lot-and-block', 'Lot and block', 'A legal description that identifies a parcel by lot and block number on a subdivision plat recorded with the county. Also called the recorded plat system.', 'N1.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-rectangular-survey', 'Rectangular survey system', 'The government survey system that divides land into townships and sections using meridians and base lines.', 'N1.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-township', 'Township', 'In the rectangular survey system, a square of land 6 miles on each side, containing 36 sections.', 'N1.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-section', 'Section', 'One square mile of land in the rectangular survey system, containing 640 acres.', 'N1.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-acre', 'Acre', 'A unit of land area equal to 43,560 square feet.', 'N1.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-area-preference', 'Area preference (situs)', 'The economic characteristic that people prefer some locations over others, which drives value.', 'N1.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-uniqueness', 'Uniqueness', 'The physical characteristic that no two parcels of land are identical. Also called nonhomogeneity.', 'N1.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-encumbrance', 'Encumbrance', 'Any claim, right, or interest in a property held by someone other than the owner that may lower its value or limit its use.', 'N1.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-lien', 'Lien', 'A claim against property that secures payment of a debt. Every lien is an encumbrance.', 'N1.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-specific-lien', 'Specific lien', 'A lien against one particular property, such as a mortgage, property tax lien, or mechanic''s lien.', 'N1.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-general-lien', 'General lien', 'A lien against all of a debtor''s property, such as a judgment lien or a federal tax lien.', 'N1.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-mechanics-lien', 'Mechanic''s lien', 'A specific lien filed by someone who supplied labor or materials to improve a property and was not paid.', 'N1.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-easement-appurtenant', 'Easement appurtenant', 'An easement that benefits a neighboring parcel. It runs with the land and transfers automatically when either parcel is sold.', 'N1.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-easement-in-gross', 'Easement in gross', 'An easement that benefits a person or company rather than a neighboring parcel, such as a utility easement.', 'N1.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-dominant-tenement', 'Dominant tenement', 'The parcel that benefits from an easement appurtenant.', 'N1.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-servient-tenement', 'Servient tenement', 'The parcel burdened by an easement, which must allow the use.', 'N1.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-easement-by-necessity', 'Easement by necessity', 'An easement created by law to give a landlocked parcel access to a road.', 'N1.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-license-land', 'License (in land)', 'Personal, revocable permission to enter or use land for a specific purpose. It is not an interest in the land.', 'N1.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-encroachment', 'Encroachment', 'An improvement, such as a fence or garage, that extends onto a neighbor''s property. Usually revealed by a survey.', 'N1.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-lis-pendens', 'Lis pendens', 'A recorded notice that a lawsuit affecting title to a property is pending.', 'N1.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-estate', 'Estate', 'The degree, quantity, and duration of a person''s interest in real property.', 'N1.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-freehold-estate', 'Freehold estate', 'An ownership estate of indefinite duration, such as a fee simple or life estate.', 'N1.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-fee-simple-absolute', 'Fee simple absolute', 'The most complete form of ownership: unlimited duration, inheritable, and with no conditions attached.', 'N1.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-fee-simple-defeasible', 'Fee simple defeasible', 'A fee estate that can be lost if a stated condition is broken. Includes fee simple determinable and fee simple subject to a condition subsequent.', 'N1.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-life-estate', 'Life estate', 'A freehold estate that lasts for the lifetime of a named person.', 'N1.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-pur-autre-vie', 'Life estate pur autre vie', 'A life estate measured by the life of someone other than the life tenant.', 'N1.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-remainderman', 'Remainderman', 'A third party named to receive the property when a life estate ends.', 'N1.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-reversion', 'Reversion', 'The return of property to the original grantor or their heirs when a life estate ends and no remainderman was named.', 'N1.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-waste', 'Waste', 'Damage or neglect by a life tenant or tenant that lowers the property''s value for those who own the future interest.', 'N1.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-leasehold-estate', 'Leasehold estate', 'A tenant''s non-freehold interest in property for the term of a lease.', 'N1.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-estate-for-years', 'Estate for years', 'A leasehold with a definite start and end date. It ends on its own without notice.', 'N1.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-periodic-tenancy', 'Periodic tenancy', 'A leasehold that renews automatically for successive periods, such as month to month, until either party gives notice.', 'N1.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-tenancy-at-will', 'Tenancy at will', 'A leasehold of no fixed length that either party may end at any time with proper notice.', 'N1.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-tenancy-at-sufferance', 'Tenancy at sufferance', 'The status of a tenant who stays after the lease ends without the landlord''s consent.', 'N1.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-severalty', 'Ownership in severalty', 'Ownership by one person or one legal entity alone.', 'N1.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-tenancy-in-common', 'Tenancy in common', 'Co-ownership of undivided interests that may be unequal, with no right of survivorship. Each share passes to the owner''s heirs or devisees.', 'N1.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-joint-tenancy', 'Joint tenancy', 'Co-ownership with equal shares and right of survivorship. It requires the four unities of possession, interest, time, and title.', 'N1.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-right-of-survivorship', 'Right of survivorship', 'When a co-owner dies, their interest passes automatically to the surviving co-owners rather than to heirs.', 'N1.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-four-unities', 'Four unities', 'Possession, interest, time, and title: the four conditions required to create a joint tenancy.', 'N1.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-partition', 'Partition', 'A court action that divides co-owned property, or orders it sold, when the co-owners cannot agree.', 'N1.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-trust', 'Trust', 'An arrangement in which a trustor transfers property to a trustee, who holds legal title for the benefit of a beneficiary.', 'N1.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-llc', 'Limited liability company (LLC)', 'A business entity whose members have limited personal liability and can choose pass-through taxation.', 'N1.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-limited-partnership', 'Limited partnership', 'A partnership with at least one general partner who manages and is fully liable, and limited partners whose risk is limited to their investment.', 'N1.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-condominium', 'Condominium', 'Ownership of a unit in fee simple plus an undivided interest in the common elements shared with the other unit owners.', 'N1.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-common-elements', 'Common elements', 'The parts of a condominium owned together by all unit owners, such as the land, hallways, roof, and pool.', 'N1.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-limited-common-elements', 'Limited common elements', 'Common elements reserved for one or a few units, such as an assigned parking space or a balcony.', 'N1.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-declaration', 'Declaration (master deed)', 'The recorded document that creates a condominium or planned community and sets its rules.', 'N1.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-cooperative', 'Cooperative', 'A building owned by a corporation. Residents buy shares in the corporation and receive a proprietary lease to their unit.', 'N1.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-proprietary-lease', 'Proprietary lease', 'The lease a cooperative shareholder receives that gives them the right to occupy a specific unit.', 'N1.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-pud', 'Planned unit development (PUD)', 'A development where owners hold title to their own lot and home while an association owns the common areas.', 'N1.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-timeshare-estate', 'Timeshare estate', 'A real property ownership interest in a unit for a recurring period of time.', 'N1.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-timeshare-use', 'Timeshare use', 'A right to use a unit for a set period, without an ownership interest in the real estate.', 'N1.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-assessment', 'Assessment (HOA)', 'A charge an owners'' association levies on owners to pay for shared expenses and reserves.', 'N1.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-trust-account', 'Trust account', 'A separate bank account a broker uses to hold other people''s money, like earnest money and rents. Also called an escrow or client trust account.', 'N10.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-commingling', 'Commingling', 'Mixing client or customer funds with the broker''s own business or personal money. Prohibited.', 'N10.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-conversion', 'Conversion', 'Using client or customer funds for the licensee''s own purposes. A form of theft.', 'N10.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-reconciliation', 'Reconciliation', 'Regularly matching the trust account''s bank balance to the broker''s records of what is owed to each client.', 'N10.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-trust-funds', 'Trust funds', 'Money or valuables a licensee receives on behalf of others in a real estate transaction.', 'N10.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-fair-housing-act', 'Fair Housing Act', 'Title VIII of the Civil Rights Act of 1968, as amended. It bans housing discrimination based on race, color, religion, sex, national origin, disability, and familial status.', 'N10.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-civil-rights-1866', 'Civil Rights Act of 1866', 'A federal law that bans all racial discrimination in property transactions, with no exceptions.', 'N10.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-familial-status', 'Familial status', 'Protection for households with children under 18, pregnant people, and people getting custody of a child.', 'N10.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-steering', 'Steering', 'Channeling buyers or renters toward or away from areas based on a protected class.', 'N10.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-blockbusting', 'Blockbusting', 'Inducing owners to sell by claiming that people of a protected class are moving into the neighborhood. Also called panic peddling.', 'N10.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-redlining', 'Redlining', 'Refusing to lend or insure in certain areas based on the racial or ethnic makeup of the area rather than on borrower qualifications.', 'N10.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-reasonable-modification', 'Reasonable modification', 'A physical change to a dwelling, such as a grab bar or ramp, that a person with a disability may make, usually at their own expense.', 'N10.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-reasonable-accommodation', 'Reasonable accommodation', 'A change in rules or policies, such as allowing an assistance animal in a no-pet building, so a person with a disability can use the housing.', 'N10.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-housing-older-persons', 'Housing for older persons', 'Communities exempt from familial status rules: all residents 62+, or at least 80% of occupied units with one resident 55+ meeting HUD rules.', 'N10.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-ada', 'Americans with Disabilities Act (ADA)', 'A federal law requiring accessibility in public accommodations and commercial facilities, including real estate offices and leasing offices.', 'N10.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-hud', 'HUD', 'The U.S. Department of Housing and Urban Development, which enforces the Fair Housing Act.', 'N10.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-blind-ad', 'Blind ad', 'An ad that doesn''t identify the brokerage or that the advertiser is a licensee. Generally prohibited.', 'N10.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-bait-and-switch', 'Bait and switch', 'Advertising a property you don''t intend to sell, or that isn''t available, to lure buyers toward something else.', 'N10.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-do-not-call', 'National Do Not Call Registry', 'A federal list of numbers telemarketers may not call. Sellers must check it and honor it, with limited exceptions.', 'N10.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-tcpa', 'Telephone Consumer Protection Act (TCPA)', 'A federal law restricting telemarketing calls, autodialed and prerecorded calls and texts, and unsolicited faxes.', 'N10.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-can-spam', 'CAN-SPAM Act', 'A federal law for commercial email: no misleading headers, a working opt-out, honored promptly, and a valid physical address.', 'N10.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-sherman-act', 'Sherman Antitrust Act', 'The federal law that bans agreements in restraint of trade, such as price fixing and boycotts.', 'N10.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-price-fixing', 'Price fixing', 'Competitors agreeing on prices or commission rates. Illegal.', 'N10.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-group-boycott', 'Group boycott', 'Competitors agreeing not to do business with a person or firm. Illegal.', 'N10.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-market-allocation', 'Market allocation', 'Competitors agreeing to divide markets by area, price range, or type of customer. Illegal.', 'N10.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-tie-in', 'Tie-in arrangement', 'Conditioning the sale of one product or service on buying another, such as requiring a buyer to list with the broker to buy a lot. Illegal.', 'N10.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-independent-contractor', 'Independent contractor', 'A licensee who controls how they do the work, is paid by results, and pays their own taxes. Most salespeople work this way.', 'N10.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-employee', 'Employee', 'A worker the employer controls in how the work is done, with taxes withheld and employee benefits.', 'N10.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-statutory-nonemployee', 'Statutory nonemployee', 'An IRS category for licensed real estate agents treated as non-employees for tax purposes when paid on results under a written contract that says so.', 'N10.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-broker-supervision', 'Broker supervision', 'The broker''s legal responsibility to supervise the licensees and staff who work under them.', 'N10.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-eo-insurance', 'Errors and omissions (E&O) insurance', 'Professional liability insurance that covers licensees for negligent mistakes. It doesn''t cover fraud or intentional acts.', 'N10.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-wire-fraud', 'Wire fraud', 'A scam in which criminals send fake wiring instructions, often from a hacked or spoofed email, to steal closing funds.', 'N10.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-risk-management', 'Risk management', 'Practices that reduce the chance and cost of mistakes: using forms, documenting, disclosing, staying within your expertise, and insuring.', 'N10.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-record-retention', 'Record retention', 'Keeping transaction and trust records for the time state law requires.', 'N10.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-code-of-ethics', 'Code of Ethics', 'Standards of conduct adopted by a professional association, such as REALTORS®. Different from license law, which comes from the state.', 'N10.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-agency', 'Agency', 'A relationship in which one person (the agent) is authorized to act on behalf of another (the principal) in dealings with third parties.', 'N5.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-principal', 'Principal', 'The person who hires an agent and is owed fiduciary duties. Also called the client.', 'N5.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-customer', 'Customer', 'A party to a transaction who is not represented by the agent. Owed honesty and fair dealing, not fiduciary duties.', 'N5.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-universal-agent', 'Universal agent', 'An agent authorized to do anything the principal could lawfully do, such as under a broad power of attorney.', 'N5.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-general-agent', 'General agent', 'An agent authorized to handle a range of matters in a particular business, like a property manager, or a salesperson for their broker.', 'N5.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-special-agent', 'Special agent', 'An agent authorized to do one specific task, like a listing broker finding a buyer. Most real estate brokers are special agents of their clients.', 'N5.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-subagent', 'Subagent', 'An agent of an agent: for example, a cooperating broker who works for the listing broker on behalf of the seller.', 'N5.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-dual-agency', 'Dual agency', 'One agent or brokerage representing both buyer and seller in the same transaction. Requires informed written consent where allowed.', 'N5.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-designated-agency', 'Designated (assigned) agency', 'A broker assigns different licensees in the same firm to represent the buyer and the seller separately. Nevada uses the term assigned agency.', 'N5.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-transaction-broker', 'Transaction broker', 'A licensee who helps parties complete a deal without representing either one. Also called a facilitator; the term and its rules vary by state.', 'N5.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-single-agency', 'Single agency', 'Representing only one party in a transaction.', 'N5.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-express-agency', 'Express agency', 'An agency created by a stated agreement, oral or written, such as a listing or buyer agreement.', 'N5.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-implied-agency', 'Implied agency', 'An agency created by the conduct of the agent and principal, without a stated agreement.', 'N5.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-ratification', 'Ratification', 'Creating agency after the fact, when a principal approves an act the agent did without authority.', 'N5.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-ostensible-agency', 'Ostensible agency (agency by estoppel)', 'Agency the law recognizes because the principal led a third party to reasonably believe someone was their agent.', 'N5.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-coupled-interest', 'Agency coupled with an interest', 'An agency in which the agent has an ownership interest in the property. The principal cannot revoke it.', 'N5.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-renunciation', 'Renunciation', 'An agent ending the agency by giving it up. The agent may be liable for damages if it breaches the contract.', 'N5.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-revocation', 'Revocation', 'A principal ending the agency by withdrawing the agent''s authority. The principal may owe damages if it breaches the contract.', 'N5.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-fiduciary', 'Fiduciary', 'A person in a position of trust who must act in the best interest of another. An agent is a fiduciary to the principal.', 'N5.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-oldcar', 'OLDCAR', 'A memory aid for the fiduciary duties: Obedience, Loyalty, Disclosure, Confidentiality, Accounting, Reasonable care.', 'N5.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-obedience', 'Obedience', 'The duty to follow the principal''s lawful instructions.', 'N5.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-loyalty', 'Loyalty', 'The duty to put the principal''s interests above everyone else''s, including the agent''s own.', 'N5.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-disclosure-duty', 'Disclosure (to the principal)', 'The duty to tell the principal every material fact the agent learns that could affect the principal''s decisions.', 'N5.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-confidentiality', 'Confidentiality', 'The duty to keep the principal''s private information private. It continues after the agency ends.', 'N5.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-accounting', 'Accounting', 'The duty to safeguard and account for all money and property received for the principal.', 'N5.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-reasonable-care', 'Reasonable care and diligence', 'The duty to use the skill and care a competent licensee would use.', 'N5.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-power-of-attorney', 'Power of attorney', 'A written document giving someone (an attorney-in-fact) authority to act for another. Real estate uses must usually be recorded to convey property.', 'N5.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-misrepresentation', 'Misrepresentation', 'A false statement or concealment of a material fact. It may be intentional (fraud) or negligent.', 'N5.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-fraud', 'Fraud', 'An intentional misrepresentation of a material fact that someone relies on and is harmed by.', 'N5.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-negligent-misrep', 'Negligent misrepresentation', 'A false statement made without reasonable care to find out the truth, even without intent to deceive.', 'N5.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-puffing', 'Puffing', 'Exaggerated opinions, like "best view in town," that a reasonable person wouldn''t take as fact. Not misrepresentation, but crossing into false facts is.', 'N5.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-material-fact', 'Material fact', 'A fact that would affect a reasonable person''s decision to buy, sell, or set a price.', 'N5.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-latent-defect', 'Latent defect', 'A hidden defect not discoverable by ordinary inspection, such as a cracked slab under flooring.', 'N5.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-caveat-emptor', 'Caveat emptor', '"Let the buyer beware." The old rule that buyers take property as is. Modern disclosure laws limit it heavily.', 'N5.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-agency-disclosure', 'Agency disclosure', 'Telling the parties in writing whom the licensee represents, at the time and in the form state law requires.', 'N5.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-conflict-of-interest', 'Conflict of interest', 'A situation where the licensee''s own interests, or another client''s, could pull against the client''s interests.', 'N5.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-self-dealing', 'Self-dealing', 'An agent acting for their own benefit in a client''s transaction, such as secretly buying the listing. Prohibited without full disclosure and consent.', 'N5.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-secret-profit', 'Secret profit', 'Money or benefit an agent receives in a transaction without the principal''s knowledge. A breach of loyalty.', 'N5.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-undisclosed-dual', 'Undisclosed dual agency', 'Representing both parties without telling them and getting consent. A serious violation that can cost the agent the commission and the license.', 'N5.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-referral-fee', 'Referral fee', 'A payment to another licensee for referring a client. Must be disclosed and paid through the broker as state law requires.', 'N5.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-contract', 'Contract', 'A legally enforceable promise or set of promises between two or more competent parties to do or not do something lawful.', 'N7.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-essential-elements', 'Essential elements of a contract', 'Competent parties, offer and acceptance (mutual assent), consideration, and a legal purpose. Real estate sale contracts must also be in writing and signed.', 'N7.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-consideration', 'Consideration', 'Something of legal value exchanged by the parties, such as money, a promise, or an act.', 'N7.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-void', 'Void contract', 'An agreement with no legal effect from the start, such as one with an illegal purpose.', 'N7.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-voidable', 'Voidable contract', 'A contract that is valid until the party with the right to cancel chooses to do so, such as one signed by a minor or under duress.', 'N7.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-unenforceable', 'Unenforceable contract', 'A contract that appears valid but cannot be enforced in court, such as an oral agreement to sell land.', 'N7.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-statute-of-frauds', 'Statute of frauds', 'The law requiring certain contracts, including contracts to sell real estate, to be in writing and signed to be enforceable.', 'N7.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-bilateral', 'Bilateral contract', 'A contract in which both parties exchange promises, such as a purchase agreement.', 'N7.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-unilateral', 'Unilateral contract', 'A contract in which only one party makes a promise and the other may act to accept, such as an option.', 'N7.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-executory', 'Executory contract', 'A contract that has not yet been fully performed, such as a purchase agreement before closing.', 'N7.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-executed', 'Executed contract', 'A contract that both parties have fully performed.', 'N7.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-express-contract', 'Express contract', 'A contract whose terms are stated in words, either written or spoken.', 'N7.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-implied-contract', 'Implied contract', 'A contract created by the parties'' conduct rather than by stated words.', 'N7.1', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-assignment', 'Assignment', 'Transferring your rights under a contract to someone else. The original party usually stays liable unless released.', 'N7.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-novation', 'Novation', 'Replacing an old contract or party with a new one, which releases the original party from liability.', 'N7.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-rescission', 'Rescission', 'Canceling a contract and returning the parties to where they were before it was made.', 'N7.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-specific-performance', 'Specific performance', 'A court order requiring a party to do what the contract says, often used in real estate because every parcel is unique.', 'N7.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-compensatory-damages', 'Compensatory damages', 'Money a court awards to cover the actual loss caused by a breach.', 'N7.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-liquidated-damages', 'Liquidated damages', 'An amount agreed to in advance as the damages for a breach, often the buyer''s earnest money.', 'N7.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-breach', 'Breach of contract', 'Failure to perform a contract obligation without a legal excuse.', 'N7.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-time-of-essence', 'Time is of the essence', 'A clause requiring deadlines in the contract to be met exactly. Missing one is a breach.', 'N7.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-statute-of-limitations', 'Statute of limitations', 'The time limit set by law for filing a lawsuit.', 'N7.2', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-listing-agreement', 'Listing agreement', 'An employment contract between a property owner and a broker to market the property.', 'N7.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-exclusive-right-to-sell', 'Exclusive right to sell', 'A listing in which the broker earns a commission no matter who sells the property, including the owner.', 'N7.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-exclusive-agency', 'Exclusive agency listing', 'A listing with one broker, but the owner owes no commission if the owner finds the buyer without help.', 'N7.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-open-listing', 'Open listing', 'A nonexclusive listing the owner may give to several brokers. Only the broker who is the procuring cause is paid.', 'N7.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-net-listing', 'Net listing', 'A listing in which the broker keeps everything above the seller''s stated net. Illegal or discouraged in many states because of the conflict of interest.', 'N7.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-procuring-cause', 'Procuring cause', 'The broker whose efforts started an unbroken chain of events that resulted in the sale.', 'N7.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-protection-clause', 'Protection (safety) clause', 'A listing clause that entitles the broker to a commission if the property sells after expiration to a buyer the broker introduced during the listing.', 'N7.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-mls', 'Multiple listing service (MLS)', 'A cooperative database where member brokers share listings.', 'N7.3', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-buyer-agency-agreement', 'Buyer agency agreement', 'A written contract creating an agency relationship between a buyer and a broker, stating the broker''s duties and compensation.', 'N7.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-exclusive-buyer-agency', 'Exclusive buyer agency agreement', 'A buyer agreement in which the buyer works with only one broker, who is paid if the buyer purchases during the term.', 'N7.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-nonexclusive-buyer', 'Nonexclusive buyer agreement', 'A buyer agreement that lets the buyer work with other brokers. The broker is paid only if they are the procuring cause.', 'N7.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-tenant-rep', 'Tenant representation agreement', 'A written agreement in which a broker represents a person looking to lease property.', 'N7.4', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-offer', 'Offer', 'A proposal by one party (offeror) to enter a contract on stated terms.', 'N7.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-acceptance', 'Acceptance', 'The offeree''s unconditional agreement to every term of an offer, communicated to the offeror.', 'N7.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-counteroffer', 'Counteroffer', 'A response that changes any term of an offer. It rejects the original offer and becomes a new offer.', 'N7.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-earnest-money', 'Earnest money', 'A deposit the buyer makes to show good faith. It is held in trust and usually applied to the purchase price at closing.', 'N7.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-contingency', 'Contingency', 'A condition that must be met before a contract becomes binding or must be performed, such as financing or inspection.', 'N7.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-equitable-title', 'Equitable title', 'A buyer''s interest in property after signing a purchase agreement but before receiving legal title.', 'N7.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-offeror', 'Offeror', 'The person who makes an offer.', 'N7.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-offeree', 'Offeree', 'The person to whom an offer is made.', 'N7.5', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-option', 'Option', 'A contract in which an owner (optionor) gives another (optionee) the right to buy or lease at set terms within a set time, for consideration.', 'N7.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-optionor', 'Optionor', 'The owner who grants an option and is bound to sell if the option is exercised.', 'N7.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-optionee', 'Optionee', 'The person who holds an option and may choose whether to exercise it.', 'N7.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-right-of-first-refusal', 'Right of first refusal', 'A right to buy or lease a property by matching another offer before the owner accepts it.', 'N7.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-land-contract', 'Land contract', 'A seller-financed sale where the buyer pays in installments and gets possession, but the seller keeps legal title until paid. Also called a contract for deed or installment contract.', 'N7.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('t-vendor-vendee', 'Vendor and vendee', 'In a land contract, the vendor is the seller who keeps legal title, and the vendee is the buyer who holds equitable title.', 'N7.6', null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified')
insert into public.concept_cards (id, subtopic_id, title, body, example, memory_hook, term_ids, citation, outline_version, status) values
  ('c-N1.1-a', 'N1.1', 'Real vs. personal property', 'Real property is the land, anything permanently attached to it, and the owner''s bundle of rights. Personal property moves.', 'A Henderson seller''s built-in pool goes with the house. The patio furniture beside it does not.', 'If it moves, it''s personal. If it''s part of the place, it''s real.', array['t-real-property','t-personal-property','t-bundle-of-rights']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.1-b', 'N1.1', 'Is it a fixture?', 'When an item gets attached, courts ask: how it was attached, whether it was adapted to the property, the relationship of the parties, what the person intended, and whether there''s a written agreement. Intent carries the most weight.', 'A Reno seller wants to keep a wall-mounted TV. Put the exclusion in writing.', 'MARIA decides whether it stays.', array['t-fixture','t-annexation']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.1-c', 'N1.1', 'Trade fixtures and emblements', 'A commercial tenant''s business equipment stays the tenant''s property. The tenant removes it before the lease ends and repairs the damage. Annual crops a tenant planted are emblements, and the tenant may harvest them.', 'A Las Vegas pizzeria bolts in its oven. At lease end, the oven leaves with the tenant.', 'Trade fixtures travel with the trade.', array['t-trade-fixture','t-emblements','t-severance']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.2-a', 'N1.2', 'What makes land different', 'Physically, land is immobile, indestructible, and unique. Economically, it is scarce, improvements change its value, investments in it are long-term, and location preference drives price.', 'Two identical floor plans in Summerlin can sell for different prices because one backs a golf course.', 'Land is I-I-U: immobile, indestructible, unique.', array['t-uniqueness','t-area-preference']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.2-b', 'N1.2', 'Three ways to describe land', 'Metes and bounds walks the boundary from a point of beginning and back. Lot and block points to a recorded subdivision plat. The rectangular survey grids land into townships and sections. A street address is never a legal description.', 'Most Las Vegas tract homes are described by lot and block.', 'Metes and bounds must come home.', array['t-legal-description','t-metes-and-bounds','t-point-of-beginning','t-lot-and-block']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.2-c', 'N1.2', 'Township and section math', 'A township is 6 miles square and holds 36 sections. A section is 1 square mile, or 640 acres. An acre is 43,560 square feet. To find acres in a description, start with 640 and multiply by each fraction.', 'The NE 1/4 of the SW 1/4 is 640 × 1/4 × 1/4 = 40 acres.', '6, 36, 640.', array['t-rectangular-survey','t-township','t-section','t-acre']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.3-a', 'N1.3', 'Liens', 'A lien secures a debt with property. Specific liens hit one property: mortgages, property taxes, mechanic''s liens. General liens hit everything the debtor owns: judgments, IRS liens. Property taxes and special assessments get paid first. Most others rank by recording date.', 'An unpaid Reno contractor files a mechanic''s lien on the house they remodeled.', 'Taxes take the front seat. Everyone else lines up by recording date.', array['t-lien','t-specific-lien','t-general-lien','t-mechanics-lien','t-encumbrance']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.3-b', 'N1.3', 'Easements', 'An easement is a right to use someone else''s land. Appurtenant easements benefit a neighboring parcel (dominant) and burden another (servient), and they run with the land. Easements in gross benefit a person or company, like a utility.', 'A Lake Tahoe cabin''s driveway crosses the neighbor''s lot. Sell either lot and the easement stays.', 'Dominant dines. Servient serves.', array['t-easement-appurtenant','t-easement-in-gross','t-dominant-tenement','t-servient-tenement','t-easement-by-necessity']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.3-c', 'N1.3', 'Licenses and encroachments', 'A license is personal, revocable permission to use land. It''s not an interest in the land. An encroachment is an improvement that crosses onto a neighbor''s lot. A survey usually finds it.', 'A Henderson buyer''s survey shows the neighbor''s fence sits two feet onto the lot.', 'A license is a permission slip. An encroachment is a trespass that stayed.', array['t-license-land','t-encroachment','t-lis-pendens']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.4-a', 'N1.4', 'Fee simple estates', 'Fee simple absolute is the most complete ownership: unlimited, inheritable, no strings. A defeasible fee can be lost. "So long as" language ends ownership automatically when the condition breaks. "But if" language requires the grantor to act.', 'Land deeded to a Carson City church "so long as" it''s used for worship reverts if it becomes a parking lot.', '"So long as" snaps back. "But if" needs a push.', array['t-fee-simple-absolute','t-fee-simple-defeasible','t-freehold-estate','t-estate']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.4-b', 'N1.4', 'Life estates', 'A life estate lasts for someone''s lifetime. When it ends, the property goes to a named remainderman or reverts to the grantor. The life tenant may live there, rent it, or sell the life interest, but may not commit waste.', 'A mother deeds her Reno home to her son for life, then to her granddaughter. The granddaughter is the remainderman.', 'Remainder goes forward. Reversion goes back.', array['t-life-estate','t-pur-autre-vie','t-remainderman','t-reversion','t-waste']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.4-c', 'N1.4', 'Leasehold estates', 'Tenants hold leaseholds, not freeholds. An estate for years has a fixed end and needs no notice. A periodic tenancy renews until someone gives notice. A tenancy at will has no set term. A tenancy at sufferance is a holdover without consent.', 'A Las Vegas tenant stays past the lease end without permission: tenancy at sufferance.', 'Years ends itself. Periodic repeats. Will is whenever. Sufferance is uninvited.', array['t-leasehold-estate','t-estate-for-years','t-periodic-tenancy','t-tenancy-at-will','t-tenancy-at-sufferance']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.5-a', 'N1.5', 'Severalty and tenancy in common', 'Severalty means one owner. Tenants in common own undivided shares that can be unequal, can sell without permission, and pass their share to heirs. There is no survivorship.', 'Two friends buy a Reno duplex 60/40 as tenants in common. If one dies, that share goes to their heirs.', 'Severalty is solo.', array['t-severalty','t-tenancy-in-common','t-partition']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.5-b', 'N1.5', 'Joint tenancy', 'Joint tenants own equal shares with right of survivorship. Creating one takes four unities: possession, interest, time, and title. If one joint tenant sells, the buyer becomes a tenant in common with the others.', 'Three siblings own a Henderson home as joint tenants. One dies, and the other two own it all.', 'PITT: break a unity, break the survivorship.', array['t-joint-tenancy','t-right-of-survivorship','t-four-unities']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.5-c', 'N1.5', 'Entities and trusts', 'A corporation owns property in severalty. LLC members get limited liability and flexible taxes. Limited partners risk only their investment. In a trust, the trustor creates it, the trustee holds legal title, and the beneficiary benefits.', 'A Las Vegas investor holds rentals in an LLC to separate them from personal assets.', 'Trustor sets it up. Trustee holds it. Beneficiary enjoys it.', array['t-trust','t-llc','t-limited-partnership']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.6-a', 'N1.6', 'Condominiums', 'A condo owner holds fee title to the unit plus an undivided share of the common elements. Each unit has its own deed, mortgage, and tax bill. A recorded declaration creates the condo, and the association collects assessments.', 'A high-rise owner near the Strip owns unit 2104 and shares the pool and lobby.', 'Condo: own the box, share the rest.', array['t-condominium','t-common-elements','t-limited-common-elements','t-declaration','t-assessment']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.6-b', 'N1.6', 'Cooperatives', 'In a co-op, a corporation owns the building. Residents buy shares and get a proprietary lease to a unit. There''s usually one blanket mortgage, so if neighbors stop paying, everyone else may have to cover.', 'A buyer comparing a co-op and a condo learns the co-op board must approve them first.', 'Co-op: you own stock, not a unit.', array['t-cooperative','t-proprietary-lease']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N1.6-c', 'N1.6', 'PUDs and timeshares', 'In a PUD, you own your lot and home, and the association owns the common areas. A timeshare estate is real property ownership of a recurring time slot. A timeshare use is only the right to use it.', 'A Henderson PUD owner owns the house and yard. The association owns the park and the gate.', 'A timeshare estate owns a slice of time. A timeshare use rents it.', array['t-pud','t-timeshare-estate','t-timeshare-use']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.1-a', 'N10.1', 'Other people''s money', 'Earnest money, rents and deposits belong to clients and customers, not the broker. They go in a separate trust account. Mixing them with the broker''s own money is commingling. Using them is conversion.', 'A Henderson broker deposits a buyer''s earnest money in the trust account, never the operating account.', 'Their money, separate account.', array['t-trust-account','t-trust-funds','t-commingling','t-conversion']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.1-b', 'N10.1', 'Records and reconciliation', 'Brokers keep records for every dollar in and out of trust, by client, and reconcile the account to the bank regularly. The broker is responsible even when staff handle the money.', 'A Las Vegas property manager reconciles the trust account monthly and catches a misposted rent.', 'Every dollar has a name.', array['t-reconciliation']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.1-c', 'N10.1', 'When the money is disputed', 'When buyer and seller both claim the earnest money, the broker can''t decide who gets it. The funds stay in trust until the parties agree in writing or a court or authorized process decides.', 'A Reno deal falls apart and both sides demand the deposit. The broker holds it and documents both demands.', 'Disputed money doesn''t move on your say-so.', array['t-trust-account']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.2-a', 'N10.2', 'Protected classes', 'The federal Fair Housing Act protects race, color, religion, sex, national origin, disability, and familial status. The 1866 Civil Rights Act bans all racial discrimination, with no exceptions. Nevada adds more classes.', 'A Las Vegas landlord can''t refuse families with children unless the property qualifies as housing for older persons.', 'Seven federal classes; race has zero exceptions.', array['t-fair-housing-act','t-civil-rights-1866','t-familial-status','t-hud']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.2-b', 'N10.2', 'Steering, blockbusting, redlining', 'Steering channels people toward or away from areas based on a protected class. Blockbusting scares owners into selling by citing who''s moving in. Redlining denies loans or insurance by area instead of by qualifications.', 'A Reno agent tells a buyer, "You''d be more comfortable in another neighborhood." That''s steering.', 'Steer, scare, or redline: all illegal.', array['t-steering','t-blockbusting','t-redlining']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.2-c', 'N10.2', 'Disability: modifications and accommodations', 'Tenants with disabilities may make reasonable modifications, usually at their own cost. Landlords must make reasonable accommodations in rules, like allowing an assistance animal. Exemptions never apply when a licensee is involved.', 'A Henderson apartment with a no-pets rule must allow a tenant''s assistance animal.', 'Modify the place. Accommodate the rules.', array['t-reasonable-modification','t-reasonable-accommodation','t-housing-older-persons','t-ada']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.3-a', 'N10.3', 'Truth in advertising', 'Ads must be accurate and must not be blind: they need to show the brokerage as required. Bait and switch, advertising something unavailable to lure buyers, is deceptive. The broker supervises all advertising.', 'A Las Vegas agent''s social media post includes the brokerage name and doesn''t overstate square footage.', 'Name the brokerage. Tell the truth.', array['t-blind-ad','t-bait-and-switch']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.3-b', 'N10.3', 'Calls, texts, and email', 'Check the Do Not Call Registry before cold calling. Federal rules limit autodialed and prerecorded calls and marketing texts without consent. Marketing email must have a working opt-out and a physical address.', 'A Reno agent scrubs a call list against the registry before a neighborhood prospecting campaign.', 'Check the list. Get consent. Let them opt out.', array['t-do-not-call','t-tcpa','t-can-spam']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.3-c', 'N10.3', 'Advertising someone else''s work', 'Only advertise listings you''re authorized to market, and never present another agent''s listing or sale as yours. Before and after photos, claims like "#1 agent," and sold stats must be accurate and supportable.', 'A Henderson agent shares a colleague''s listing only with permission and with the listing brokerage named.', 'If you can''t prove it, don''t post it.', array['t-blind-ad','t-bait-and-switch']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.4-a', 'N10.4', 'Price fixing', 'Commissions are always negotiable. Competing brokers must never agree, or even discuss among themselves, what rates to charge. That''s price fixing under the Sherman Act.', 'Two Henderson brokers at lunch start talking about "standard" rates. One ends the conversation.', 'Never talk rates with the competition.', array['t-sherman-act','t-price-fixing']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.4-b', 'N10.4', 'Boycotts, allocation, tie-ins', 'Competitors may not agree to shun a firm (boycott) or divide territories or customers (market allocation). Forcing a buyer to use one service to get another is a tie-in. All are illegal.', 'Two Las Vegas brokerages agree one takes Summerlin and the other Henderson. That''s market allocation.', 'Don''t fix, boycott, divide, or tie.', array['t-group-boycott','t-market-allocation','t-tie-in']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.4-c', 'N10.4', 'Stay out of antitrust trouble', 'Set your fees on your own. Don''t discuss rates with competitors, don''t predict that others will refuse to work with a firm, and say "commissions are negotiable." Penalties include prison, big fines, and triple damages.', 'A Reno agent at a mixer changes the subject when a competitor asks what she charges.', 'Compete on value, not collusion.', array['t-sherman-act','t-price-fixing']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.5-a', 'N10.5', 'Independent contractor or employee', 'Most salespeople are independent contractors: paid by results, not hours, under a written agreement, and paying their own taxes. The IRS calls them statutory nonemployees. The broker still must supervise them under license law.', 'A Reno salesperson sets their own schedule and is paid only on closed deals.', 'Paid by results, not by hours.', array['t-independent-contractor','t-employee','t-statutory-nonemployee']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.5-b', 'N10.5', 'The broker answers for the team', 'Brokers must supervise their licensees and staff: advertising, contracts, trust money, and conduct. Salespeople are paid only through their broker.', 'A Las Vegas buyer pays a salesperson a cash bonus directly. That breaks the rule that all pay goes through the broker.', 'All pay flows through the broker.', array['t-broker-supervision']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.5-c', 'N10.5', 'Unlicensed assistants', 'Assistants without a license can schedule, file, and prepare mailings. They can''t show property, discuss price or terms, negotiate, or hold open houses alone. The licensee and broker answer for what they do.', 'A Las Vegas assistant books showings and sends lockbox codes, but the licensed agent shows the homes.', 'No license, no negotiating.', array['t-broker-supervision']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.6-a', 'N10.6', 'Managing risk', 'Use approved forms, disclose early, document everything, stay within your expertise, and carry E&O insurance. E&O covers honest mistakes, not fraud.', 'A Henderson agent emails a summary after every phone call with a client, creating a clear record.', 'Write it down, and refer what you don''t know.', array['t-risk-management','t-eo-insurance','t-record-retention']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.6-b', 'N10.6', 'Stop wire fraud', 'Criminals send fake wiring instructions from hacked or look-alike email addresses. Warn clients early. Always verify instructions by calling a known number, never one in the email.', 'A Reno buyer gets a "new wiring instructions" email the day before closing. They call the title company''s known number first.', 'Never trust a wire email. Call a known number.', array['t-wire-fraud']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N10.6-c', 'N10.6', 'Ethics vs. license law', 'License law is the state''s legal minimum, enforced by the regulator. A professional Code of Ethics, like the REALTOR® code, is set by an association for its members and can demand more.', 'A Nevada licensee who isn''t a REALTOR® must follow Nevada law, but not the association''s code.', 'Law is the floor. Ethics can raise the bar.', array['t-code-of-ethics']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N5.1-a', 'N5.1', 'Clients vs. customers', 'Your client, the principal, gets full fiduciary duties. A customer is the other party you aren''t representing. They get honesty and fair dealing, but not your loyalty or advice.', 'A Henderson listing agent''s client is the seller. The unrepresented buyer who calls on the sign is a customer.', 'Clients get loyalty. Customers get honesty.', array['t-agency','t-principal','t-customer','t-single-agency']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N5.1-b', 'N5.1', 'Universal, general, special', 'A universal agent can do anything the principal can. A general agent handles a range of matters in one business. A special agent does one specific job. A listing broker is a special agent of the seller.', 'A Las Vegas property manager collecting rent and hiring vendors for an owner is a general agent.', 'Universal: all. General: a business. Special: one task.', array['t-universal-agent','t-general-agent','t-special-agent']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N5.1-c', 'N5.1', 'Dual, assigned, and subagency', 'Dual agency means one agent or firm represents both sides; it needs informed written consent where allowed. Assigned (designated) agency puts different licensees on each side within one firm. A subagent works for the listing broker on the seller''s behalf.', 'Two agents at the same Reno brokerage each represent one side, with the broker supervising both.', 'Two clients, one firm: disclose and get consent.', array['t-dual-agency','t-designated-agency','t-subagent','t-transaction-broker']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N5.2-a', 'N5.2', 'How agency starts', 'Agency is created by express agreement, implied by conduct, by ratification after the fact, or by estoppel when a principal makes a third party believe someone is their agent.', 'A Carson City owner says nothing while a broker markets the home, then accepts the broker''s buyer. That can ratify the agency.', 'Agreement, actions, approval after, or appearances.', array['t-express-agency','t-implied-agency','t-ratification','t-ostensible-agency']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N5.2-b', 'N5.2', 'How agency ends', 'Agency ends by performance, expiration, mutual agreement, revocation by the principal, renunciation by the agent, or by law: death, incapacity, bankruptcy, or destruction of the property.', 'A Las Vegas seller''s house sells and closes. The listing agency ends by performance.', 'Done, expired, agreed, fired, quit, or law.', array['t-revocation','t-renunciation']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N5.2-c', 'N5.2', 'Agency coupled with an interest', 'If the agent owns an interest in the property, the principal can''t revoke the agency, and it doesn''t end when the principal dies.', 'A broker who co-owns a Henderson lot with the seller holds an agency coupled with an interest.', 'Own a piece, can''t be fired.', array['t-coupled-interest']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N5.3-a', 'N5.3', 'The fiduciary duties: OLDCAR', 'An agent owes the principal Obedience, Loyalty, Disclosure, Confidentiality, Accounting, and Reasonable care. These go to clients, not customers.', 'A Reno buyer''s agent keeps the buyer''s top price secret, reports every offer, and tracks the earnest money.', 'OLDCAR: the six things a client is owed.', array['t-fiduciary','t-oldcar','t-reasonable-care']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N5.3-b', 'N5.3', 'Obedience and loyalty, with limits', 'Follow the client''s lawful instructions and put their interests first. Never follow an unlawful instruction, such as refusing to show to a protected class or hiding a known defect.', 'A Las Vegas seller says don''t show to families with kids. The agent refuses; that''s illegal discrimination.', 'Obey the lawful. Refuse the unlawful.', array['t-obedience','t-loyalty']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N5.3-c', 'N5.3', 'Disclosure, confidentiality, accounting', 'Tell your client every material fact you learn. Keep their private information private, even after the agency ends. Account for every dollar you hold for them.', 'A Henderson buyer''s agent learns the seller is in foreclosure and must close fast. The agent tells the buyer.', 'Tell your client everything. Tell others nothing private.', array['t-disclosure-duty','t-confidentiality','t-accounting','t-power-of-attorney']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N5.4-a', 'N5.4', 'Duties to everyone', 'Even to customers, licensees must be honest, deal fairly, and disclose known material defects. Caveat emptor no longer protects a licensee who stays silent about a known problem.', 'A Reno listing agent knows the roof leaks. They must disclose it to buyers even though the buyers aren''t their clients.', 'Honest with everyone. Loyal to your client.', array['t-material-fact','t-latent-defect','t-caveat-emptor']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N5.4-b', 'N5.4', 'Fraud, negligence, puffing', 'Fraud is an intentional lie about a material fact. Negligent misrepresentation is a false statement made carelessly. Puffing is obvious opinion, like "gorgeous views," and isn''t actionable unless it states a false fact.', 'Saying a Summerlin home has "the best kitchen on the block" is puffing. Saying it has a new roof when it doesn''t is misrepresentation.', 'Opinion is puffing. False fact is trouble.', array['t-misrepresentation','t-fraud','t-negligent-misrep','t-puffing']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N5.4-c', 'N5.4', 'Advice you can''t give', 'Licensees must not give legal or tax advice, and must not claim expertise they lack. Recommend an attorney, CPA, inspector, or other expert when a question goes beyond real estate brokerage.', 'A Henderson seller asks how to minimize capital gains. The agent refers them to a CPA.', 'Know your lane. Refer the rest.', array['t-material-fact']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N5.5-a', 'N5.5', 'Disclose who you represent', 'State law requires telling the parties in writing whom you represent, at a set time and on required forms. Disclosure protects consumers and the licensee.', 'Nevada requires its own agency disclosure forms. You''ll learn them in the Nevada units.', 'Say who you work for before they say too much.', array['t-agency-disclosure']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N5.5-b', 'N5.5', 'Conflicts of interest', 'Disclose any personal interest in a deal: buying a listing yourself, selling to a relative, or getting a referral fee. Undisclosed conflicts, secret profits, and self-dealing breach loyalty.', 'A Las Vegas agent wants to buy a client''s home. The agent discloses in writing that they''re the buyer and that they''re licensed.', 'If it benefits you, disclose it.', array['t-conflict-of-interest','t-self-dealing','t-secret-profit','t-referral-fee']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N5.5-c', 'N5.5', 'Undisclosed dual agency', 'Representing both sides without telling them and getting consent is one of the most serious agency violations. It can cost the commission, bring discipline, and expose the licensee to lawsuits.', 'A Reno agent quietly advises both buyer and seller on price. Both can claim breach of loyalty.', 'Secret dual agency: two clients, zero loyalty.', array['t-undisclosed-dual']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.1-a', 'N7.1', 'What makes a contract valid', 'A valid contract needs competent parties, offer and acceptance, consideration, and a legal purpose. A contract to sell real estate must also be in writing and signed to be enforceable.', 'A Henderson buyer''s purchase agreement is signed by two adults, trades money for a deed, and is for a lawful sale.', 'COAL: Competent, Offer and acceptance, consideration (A deal), Legal.', array['t-contract','t-essential-elements','t-consideration','t-statute-of-frauds']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.1-b', 'N7.1', 'Void, voidable, unenforceable', 'Void means it never had legal effect, like a contract for an illegal purpose. Voidable is valid until the protected party cancels, like a minor''s contract. Unenforceable looks valid but a court won''t enforce it, like an oral land sale.', 'A 17-year-old in Reno signs a purchase agreement. The minor may cancel it. The seller may not.', 'Void is nothing. Voidable is someone''s choice.', array['t-void','t-voidable','t-unenforceable']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.1-c', 'N7.1', 'Kinds of contracts', 'Express contracts are stated in words; implied ones come from conduct. Bilateral means a promise for a promise. Unilateral means a promise for an act. Executory means not yet fully performed; executed means fully performed.', 'A Las Vegas purchase agreement is bilateral and executory until closing. After closing, it''s executed.', 'Bi means both promise. Uni means one promises.', array['t-bilateral','t-unilateral','t-executory','t-executed','t-express-contract','t-implied-contract']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.2-a', 'N7.2', 'Assignment vs. novation', 'Assignment transfers your rights to someone else, but you usually stay liable. Novation replaces the contract or a party with a new one and releases the original party.', 'A Reno buyer assigns a purchase contract to an investor. If the investor fails to close, the original buyer may still be on the hook.', 'Assign and you still sign for it. Novation sets you free.', array['t-assignment','t-novation']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.2-b', 'N7.2', 'Remedies for breach', 'When a party breaches, the other may sue for damages, ask a court for specific performance, or rescind. Because every parcel is unique, buyers can often get specific performance. Liquidated damages are set in advance, often the earnest money.', 'A Henderson seller backs out to take a higher offer. The buyer asks the court to order the sale.', 'Land is unique, so courts can make you sell.', array['t-breach','t-specific-performance','t-compensatory-damages','t-liquidated-damages','t-rescission']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.2-c', 'N7.2', 'Ending a contract', 'Contracts end by full performance, mutual agreement, impossibility, operation of law, or breach. A "time is of the essence" clause makes every deadline strict. The statute of limitations limits how long someone has to sue.', 'A Las Vegas contract says closing by June 30 and time is of the essence. Closing July 2 is a breach.', 'When time is of the essence, late is broken.', array['t-time-of-essence','t-statute-of-limitations']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.3-a', 'N7.3', 'Three kinds of listings', 'Exclusive right to sell: the broker gets paid no matter who sells. Exclusive agency: the broker gets paid unless the owner finds the buyer alone. Open listing: many brokers, and only the procuring cause gets paid.', 'A Summerlin owner on an exclusive right to sell finds a buyer at church. The broker is still owed a commission.', 'Right to sell means the right to be paid.', array['t-listing-agreement','t-exclusive-right-to-sell','t-exclusive-agency','t-open-listing','t-procuring-cause']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.3-b', 'N7.3', 'Net listings and protection clauses', 'In a net listing, the broker keeps everything above the seller''s number. That creates a conflict of interest, so many states ban or discourage it. A protection clause pays the broker if a buyer they introduced buys soon after the listing expires.', 'A Reno buyer toured with the listing agent, waited until the listing expired, then bought direct. The protection clause applies.', 'Net listing: the agent''s gain is the seller''s pain.', array['t-net-listing','t-protection-clause','t-mls']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.3-c', 'N7.3', 'How listings end', 'A listing is a personal service contract. It ends when it is performed, when it expires, by mutual agreement, or by operation of law, such as the death or incapacity of either party, bankruptcy, or destruction of the property.', 'A Henderson seller dies two weeks into a listing. The listing ends, and the estate must sign a new one.', 'Personal contract: if a person goes, the listing goes.', array['t-listing-agreement']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.4-a', 'N7.4', 'Representing buyers in writing', 'A buyer agency agreement creates the agency relationship and spells out the broker''s duties, the term, and how the broker is paid. Exclusive means one broker; nonexclusive lets the buyer use others.', 'A first-time buyer in Las Vegas signs a 90-day exclusive buyer agreement before touring homes.', 'Put the buyer''s relationship on paper before the first door opens.', array['t-buyer-agency-agreement','t-exclusive-buyer-agency','t-nonexclusive-buyer']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.4-b', 'N7.4', 'Compensation and tenants', 'The buyer agreement states what the broker will be paid and who pays it. If a seller offers less, the buyer may owe the difference. Tenants can sign representation agreements too.', 'A Reno renter hires a broker under a tenant representation agreement to find an office lease.', 'Who pays, how much, and when: write it down.', array['t-tenant-rep']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.4-c', 'N7.4', 'Ending a buyer agreement', 'Buyer agreements end like listings: when the buyer purchases, when the term expires, by mutual agreement, or by operation of law. A protection period can still pay the broker for homes shown during the term.', 'A Henderson buyer''s agreement expires, and three weeks later they buy a home their agent showed them. The protection period applies.', 'Every agreement has an exit, and a protection period.', array['t-buyer-agency-agreement','t-exclusive-buyer-agency']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.5-a', 'N7.5', 'Offer, acceptance, counteroffer', 'An offer becomes a contract when the offeree accepts every term and the acceptance is communicated. Changing any term is a counteroffer, which kills the original offer. An offer can be withdrawn any time before acceptance is communicated.', 'A Henderson seller accepts the price but changes closing from 30 to 45 days. That''s a counteroffer.', 'Change anything, and you''ve rejected everything.', array['t-offer','t-acceptance','t-counteroffer','t-offeror','t-offeree']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.5-b', 'N7.5', 'Earnest money and contingencies', 'Earnest money shows good faith and is held in trust. Contingencies, like financing, inspection, or appraisal, let a party exit or renegotiate if a condition isn''t met. Once signed, the buyer holds equitable title.', 'A Las Vegas buyer''s loan is denied. The financing contingency lets them cancel and get their deposit back.', 'Contingency: if this, then that.', array['t-earnest-money','t-contingency','t-equitable-title']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.5-c', 'N7.5', 'Multiple offers', 'Agents present every written offer to the seller promptly. The seller decides: accept one, counter one, or reject them all. A seller who sends counteroffers to several buyers at once risks two acceptances.', 'Three offers arrive on a Reno home on Saturday. The listing agent presents all three that day.', 'Present every offer. The seller picks.', array['t-offer']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.6-a', 'N7.6', 'Options', 'In an option, the owner (optionor) is bound to sell on set terms if the optionee chooses to buy within the option period. The optionee pays consideration for that right and is never obligated to buy.', 'A developer pays a Carson City owner $5,000 for a one-year option to buy 10 acres.', 'The optionee has the option. The optionor is bound.', array['t-option','t-optionor','t-optionee']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.6-b', 'N7.6', 'Right of first refusal', 'A right of first refusal doesn''t set a price. It gives the holder the chance to match a real offer before the owner accepts it. If the holder passes, the owner may sell to the other buyer.', 'A Las Vegas tenant''s lease includes a right of first refusal. When an investor offers $410,000, the tenant may match it.', 'First refusal: match it or lose it.', array['t-right-of-first-refusal']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified'),
  ('c-N7.6-c', 'N7.6', 'Land contracts', 'In a land contract, the seller finances the sale. The buyer (vendee) moves in and pays installments but holds only equitable title. The seller (vendor) keeps legal title until the contract is paid off.', 'A buyer in rural Elko County buys on a land contract and gets the deed after the final payment.', 'Pay it all, then the deed falls.', array['t-land-contract','t-vendor-vendee','t-equitable-title']::text[], null, 'Content Outlines 01/15/2025 (#092901) [verify]', 'unverified')
insert into public.questions (id, pool, exam_form_id, is_pretest, portion, topic_id, subtopic_id, outline_version, course, exercise_type, difficulty, level, prompt, options, correct, explanation, wrong_explanations, memory_hook, formula, worked_steps, citation, fact_key, status) values
  ('N1.1-01', 'lesson', null, false, 'national', 'N1', 'N1.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'Which of these is most likely real property when a house is sold?', '["A dishwasher built into the kitchen cabinets","Patio furniture on the back deck","An area rug in the living room","A freestanding refrigerator plugged into the wall"]'::jsonb, '0'::jsonb, 'A built-in dishwasher is attached and adapted to the home, so it is a fixture and part of the real property.', '["","Furniture is movable and not attached, so it is personal property.","A rug lying on the floor is not attached or adapted to the home; it is personal property.","A freestanding appliance that simply plugs in is movable personal property unless the contract says otherwise."]'::jsonb, 'If it moves, it''s personal. If it''s part of the place, it''s real.', null, '[]'::jsonb, null, 'fixture-builtin-appliance', 'unverified'),
  ('N1.1-02', 'lesson', null, false, 'national', 'N1', 'N1.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'recall', 'When a court decides whether an item is a fixture, which factor usually carries the most weight?', '["What the item cost","How long the item has been in place","Whether the item can be seen from the street","The intention of the person who attached it"]'::jsonb, '3'::jsonb, 'Intent of the person who attached the item, shown by how and why it was attached, is generally the most important fixture test.', '["Cost has nothing to do with whether something became part of the real estate.","Time in place is not one of the fixture tests.","Visibility is not a fixture test.",""]'::jsonb, 'MARIA decides, and the I in MARIA speaks loudest.', null, '[]'::jsonb, null, 'fixture-intent-most-important', 'unverified'),
  ('N1.1-03', 'lesson', null, false, 'national', 'N1', 'N1.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'application', 'A seller removes a chandelier that was wired into the dining room ceiling before closing. The purchase agreement does not mention it. Which statement is most accurate?', '["The seller may keep it because the contract is silent","The chandelier is presumed a fixture that belongs to the buyer","Light fixtures are always personal property","The buyer''s only remedy is to cancel the sale"]'::jsonb, '1'::jsonb, 'An item wired into the structure is a fixture. Unless the contract excludes it, it transfers with the property.', '["Silence in the contract means the normal rule applies: attached items are fixtures that transfer.","","Hard-wired light fixtures are a classic example of fixtures, not personal property.","The buyer can ask for the item to be returned or for a credit; cancellation is not the only remedy."]'::jsonb, 'Wired in means it stays in.', null, '[]'::jsonb, null, 'fixture-chandelier-silent-contract', 'unverified'),
  ('N1.1-04', 'lesson', null, false, 'national', 'N1', 'N1.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'scenario', 2, 'application', 'Your seller tells you they plan to take the custom drapery rods and the wall-mounted TV when they move. What should the agent do?', '["Tell the seller fixtures can be removed any time before closing","Say nothing until a buyer asks about them","Tell the seller they can never keep attached items","Write the exclusions into the listing and make sure the purchase agreement excludes them"]'::jsonb, '3'::jsonb, 'Attached items are presumed fixtures. Excluding them in writing in the listing and the purchase agreement avoids a dispute.', '["Attached items are presumed to transfer; removing them without a written exclusion can breach the contract.","Waiting invites a dispute. Exclusions should be clear from the start.","Sellers can keep attached items if the contract clearly excludes them.",""]'::jsonb, 'Want to keep it? Write it out.', null, '[]'::jsonb, null, 'fixture-exclusion-in-writing', 'unverified'),
  ('N1.1-05', 'lesson', null, false, 'national', 'N1', 'N1.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'application', 'A restaurant tenant bolted a walk-in cooler to the floor for its business. The lease is ending. Which is correct?', '["The tenant must leave it but may charge the landlord for it","The tenant may remove it before the lease ends but must repair any damage","It became the landlord''s property when it was bolted down","It may be removed only with a court order"]'::jsonb, '1'::jsonb, 'Equipment a tenant installs for business is a trade fixture. It stays the tenant''s personal property and may be removed before the lease ends, with damage repaired.', '["The tenant owns the cooler and may take it; there is no automatic sale to the landlord.","","Trade fixtures do not become the landlord''s property just because they are attached.","No court order is needed to remove trade fixtures on time."]'::jsonb, 'Trade fixtures travel with the trade.', null, '[]'::jsonb, null, 'trade-fixture-removal-rule', 'unverified'),
  ('N1.1-06', 'lesson', null, false, 'national', 'N1', 'N1.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'recall', 'A tenant moves out and leaves its trade fixtures behind after the lease expires. What usually happens to them?', '["They become the landlord''s property","The tenant keeps ownership indefinitely","They must be sold at auction","The county takes ownership"]'::jsonb, '0'::jsonb, 'Trade fixtures not removed by the end of the lease generally become the landlord''s property by accession.', '["","The right to remove trade fixtures ends when the lease ends.","Auction is not the standard rule for abandoned trade fixtures.","The county has no claim to them."]'::jsonb, 'Leave it behind, leave it to the landlord.', null, '[]'::jsonb, null, 'trade-fixture-abandoned-accession', 'unverified'),
  ('N1.1-07', 'lesson', null, false, 'national', 'N1', 'N1.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'recall', 'A tenant farmer''s lease ends early, through no fault of the tenant, before the annual crop is ripe. The tenant''s right to come back and harvest is called:', '["Emblements","Annexation","Accession","Severance"]'::jsonb, '0'::jsonb, 'Emblements are annual crops produced by labor. A tenant whose tenancy ends early through no fault of their own may return to harvest them.', '["","Annexation is attaching personal property to land.","Accession is how an owner acquires things added to their property, not a tenant''s harvest right.","Severance is detaching something from the land; it''s not the harvest right itself."]'::jsonb, 'Emblements: you planted it, you pick it.', null, '[]'::jsonb, null, 'emblements-harvest-right', 'unverified'),
  ('N1.1-08', 'lesson', null, false, 'national', 'N1', 'N1.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'tf', 1, 'recall', 'Personal property can become real property when it is permanently attached to the land.', '["True","False"]'::jsonb, '0'::jsonb, 'True. Annexation, such as building lumber into a house, turns personal property into real property.', '["","This is annexation, a core rule: attaching personal property can make it part of the real estate."]'::jsonb, 'Attach it and it can become real.', null, '[]'::jsonb, null, 'annexation-converts-personal-to-real', 'unverified'),
  ('N1.1-09', 'lesson', null, false, 'national', 'N1', 'N1.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'tf', 2, 'recall', 'A manufactured home is always classified as real property.', '["True","False"]'::jsonb, '1'::jsonb, 'False. Classification depends on whether the home is permanently affixed and how state law treats it.', '["A manufactured home can be personal property. It generally becomes real property only when permanently affixed and handled as real property under state rules.",""]'::jsonb, 'On wheels, it''s a vehicle. On a foundation, it may be real.', null, '[]'::jsonb, null, 'manufactured-home-classification', 'unverified'),
  ('N1.1-10', 'lesson', null, false, 'national', 'N1', 'N1.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'An owner cuts down standing timber and sells the logs. Turning the trees into personal property is called:', '["Annexation","Severance","Accretion","Partition"]'::jsonb, '1'::jsonb, 'Severance detaches something from the land and converts real property to personal property.', '["Annexation is the opposite: attaching personal property to land.","","Accretion is land gradually added by water deposits.","Partition divides co-owned property."]'::jsonb, 'Sever it and it''s set free.', null, '[]'::jsonb, null, 'severance-timber', 'unverified'),
  ('N1.1-11', 'lesson', null, false, 'national', 'N1', 'N1.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'A seller agrees to sell their washer and dryer to the buyer outside the home sale. Which document transfers ownership of the appliances?', '["A grant deed","A quitclaim deed","A lease","A bill of sale"]'::jsonb, '3'::jsonb, 'Personal property is transferred with a bill of sale. Deeds transfer real property.', '["Deeds transfer real property, not personal property.","A quitclaim deed is still a deed for real property.","A lease transfers possession, not ownership.",""]'::jsonb, 'Deeds for dirt. Bills for things.', null, '[]'::jsonb, null, 'bill-of-sale-personal', 'unverified'),
  ('N1.2-01', 'lesson', null, false, 'national', 'N1', 'N1.2', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'Which characteristic of land explains why no two parcels are exactly alike?', '["Scarcity","Indestructibility","Uniqueness","Immobility"]'::jsonb, '2'::jsonb, 'Uniqueness, also called nonhomogeneity, means every parcel differs at least in location.', '["Scarcity is an economic characteristic about limited supply.","Indestructibility means land itself can''t be destroyed.","","Immobility means land can''t be moved, not that every parcel differs."]'::jsonb, 'Land is I-I-U: immobile, indestructible, unique.', null, '[]'::jsonb, null, 'land-uniqueness', 'unverified'),
  ('N1.2-02', 'lesson', null, false, 'national', 'N1', 'N1.2', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'application', 'Identical homes sell for more on one side of a street because that side is zoned for a top-rated school. This illustrates:', '["Indestructibility","Area preference","Permanence of investment","Immobility"]'::jsonb, '1'::jsonb, 'Area preference, or situs, is the economic characteristic that people value some locations more than others.', '["Indestructibility is unrelated to price differences between locations.","","Permanence of investment refers to the long payback of improvements.","Immobility explains why location matters, but the preference for a location is area preference."]'::jsonb, 'Location, location, situs.', null, '[]'::jsonb, null, 'area-preference-school', 'unverified'),
  ('N1.2-03', 'lesson', null, false, 'national', 'N1', 'N1.2', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'A metes and bounds description must:', '["Begin and end at the point of beginning","Reference a recorded plat map","Include the street address","Use townships and sections"]'::jsonb, '0'::jsonb, 'A metes and bounds description must close by returning to the point of beginning.', '["","Referencing a plat is the lot and block method.","A street address is not part of a legal description.","Townships and sections belong to the rectangular survey system."]'::jsonb, 'Metes and bounds must come home.', null, '[]'::jsonb, null, 'metes-bounds-closes', 'unverified'),
  ('N1.2-04', 'lesson', null, false, 'national', 'N1', 'N1.2', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', '"Lot 14, Block 3 of the Desert Vista subdivision" is an example of which description method?', '["Rectangular survey","Lot and block (recorded plat)","Monument description","Metes and bounds"]'::jsonb, '1'::jsonb, 'Lot and block refers to a lot on a subdivision plat recorded with the county.', '["Rectangular survey uses townships, ranges, and sections.","","A monument description relies on physical markers, not a plat.","Metes and bounds uses distances and directions from a point of beginning."]'::jsonb, 'Lot and block points to the plat.', null, '[]'::jsonb, null, 'lot-block-plat', 'unverified'),
  ('N1.2-05', 'lesson', null, false, 'national', 'N1', 'N1.2', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'How many acres are in one section?', '["36","160","43,560","640"]'::jsonb, '3'::jsonb, 'A section is one square mile, which is 640 acres.', '["36 is the number of sections in a township.","160 acres is a quarter section.","43,560 is the number of square feet in one acre.",""]'::jsonb, '6, 36, 640.', null, '[]'::jsonb, null, 'section-640-acres', 'unverified'),
  ('N1.2-06', 'lesson', null, false, 'national', 'N1', 'N1.2', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'number', 2, 'calculation', 'How many acres are in the NE 1/4 of the SW 1/4 of a section?', '[]'::jsonb, '{"value":40,"tolerance":0,"unit":"acres"}'::jsonb, 'Multiply 640 by each fraction: 640 × 1/4 × 1/4 = 40 acres.', '[]'::jsonb, 'Read it backward, multiply forward.', 'Acres = 640 × each fraction in the description', '["A section has 640 acres.","SW 1/4: 640 × 1/4 = 160 acres.","NE 1/4 of that: 160 × 1/4 = 40 acres."]'::jsonb, null, 'acres-quarter-quarter', 'unverified'),
  ('N1.2-07', 'lesson', null, false, 'national', 'N1', 'N1.2', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'number', 2, 'calculation', 'How many acres are in the S 1/2 of the NW 1/4 of a section?', '[]'::jsonb, '{"value":80,"tolerance":0,"unit":"acres"}'::jsonb, '640 × 1/4 × 1/2 = 80 acres.', '[]'::jsonb, 'Read it backward, multiply forward.', 'Acres = 640 × each fraction in the description', '["A section has 640 acres.","NW 1/4: 640 × 1/4 = 160 acres.","S 1/2 of that: 160 × 1/2 = 80 acres."]'::jsonb, null, 'acres-half-quarter', 'unverified'),
  ('N1.2-08', 'lesson', null, false, 'national', 'N1', 'N1.2', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'order', 1, 'recall', 'Put these rectangular survey units in order from largest to smallest.', '["Township (36 square miles)","Section (640 acres)","Quarter section (160 acres)","Quarter-quarter section (40 acres)"]'::jsonb, '[0,1,2,3]'::jsonb, 'A township holds 36 sections; a section is 640 acres; a quarter section is 160; a quarter of that is 40.', '[]'::jsonb, '6, 36, 640, then keep quartering.', null, '[]'::jsonb, null, 'survey-units-order', 'unverified'),
  ('N1.2-09', 'lesson', null, false, 'national', 'N1', 'N1.2', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'tf', 1, 'recall', 'A street address is a sufficient legal description for a deed.', '["True","False"]'::jsonb, '1'::jsonb, 'False. A legal description must identify the exact boundaries; a street address does not.', '["Addresses change and don''t define boundaries. A deed needs a legal description such as lot and block or metes and bounds.",""]'::jsonb, 'An address finds the mailbox, not the boundary.', null, '[]'::jsonb, null, 'address-not-legal-description', 'unverified'),
  ('N1.2-10', 'lesson', null, false, 'national', 'N1', 'N1.2', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'A township in the rectangular survey system measures:', '["6 miles by 6 miles","24 miles by 24 miles","640 acres","1 mile by 1 mile"]'::jsonb, '0'::jsonb, 'A township is 6 miles square and contains 36 sections.', '["","24 miles square is the size of a check (quadrangle) formed by guide meridians and correction lines.","640 acres is one section.","1 mile by 1 mile is a section."]'::jsonb, '6, 36, 640.', null, '[]'::jsonb, null, 'township-size', 'unverified'),
  ('N1.2-11', 'lesson', null, false, 'national', 'N1', 'N1.2', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'number', 2, 'calculation', 'A rectangular parcel measures 660 feet by 1,320 feet. How many acres is it?', '[]'::jsonb, '{"value":20,"tolerance":0,"unit":"acres"}'::jsonb, '660 × 1,320 = 871,200 sq ft, and 871,200 ÷ 43,560 = 20 acres.', '[]'::jsonb, 'Square feet over 43,560 equals acres.', 'Acres = square feet ÷ 43,560', '["Area: 660 × 1,320 = 871,200 square feet.","Acres: 871,200 ÷ 43,560 = 20 acres."]'::jsonb, null, 'acres-from-dimensions', 'unverified'),
  ('N1.3-01', 'lesson', null, false, 'national', 'N1', 'N1.3', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'Which of these is a general lien?', '["A judgment lien","A mechanic''s lien","A mortgage","A real property tax lien"]'::jsonb, '0'::jsonb, 'A judgment lien can attach to all of the debtor''s property, which makes it a general lien.', '["","A mechanic''s lien attaches to the property that was improved, so it is specific.","A mortgage attaches only to the property it secures, so it is specific.","A property tax lien attaches to the taxed parcel only, so it is specific."]'::jsonb, 'Judgments go general. Mortgages stay specific.', null, '[]'::jsonb, null, 'judgment-general-lien', 'unverified'),
  ('N1.3-02', 'lesson', null, false, 'national', 'N1', 'N1.3', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'recall', 'Which lien usually takes priority over all others, regardless of when it was recorded?', '["First mortgage","Mechanic''s lien","Judgment lien","Real property tax lien"]'::jsonb, '3'::jsonb, 'Real property taxes and special assessments generally take first priority regardless of recording date.', '["A first mortgage ranks by its recording date and still falls behind property taxes.","Mechanic''s lien priority varies by state but generally falls behind property taxes.","A judgment lien ranks by when it attaches and falls behind property taxes.",""]'::jsonb, 'Taxes take the front seat.', null, '[]'::jsonb, null, 'tax-lien-priority', 'unverified'),
  ('N1.3-03', 'lesson', null, false, 'national', 'N1', 'N1.3', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'In an easement appurtenant, the parcel that benefits from the easement is the:', '["Dominant tenement","Remainder estate","Easement in gross","Servient tenement"]'::jsonb, '0'::jsonb, 'The dominant tenement benefits; the servient tenement carries the burden.', '["","A remainder estate relates to life estates, not easements.","An easement in gross benefits a person or company, not a parcel.","The servient tenement is burdened, not benefited."]'::jsonb, 'Dominant dines. Servient serves.', null, '[]'::jsonb, null, 'dominant-tenement-benefits', 'unverified'),
  ('N1.3-04', 'lesson', null, false, 'national', 'N1', 'N1.3', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'A power company''s right to run lines across private lots is best described as:', '["A license","An encroachment","An easement appurtenant","An easement in gross"]'::jsonb, '3'::jsonb, 'An easement that benefits a person or company rather than a parcel is an easement in gross. Utility easements are the classic example.', '["A license is revocable permission; utility rights are lasting interests.","An encroachment is an unauthorized intrusion, not a granted right.","An appurtenant easement benefits a neighboring parcel, not a company.",""]'::jsonb, 'In gross goes to a person or company.', null, '[]'::jsonb, null, 'utility-easement-in-gross', 'unverified'),
  ('N1.3-05', 'lesson', null, false, 'national', 'N1', 'N1.3', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'scenario', 2, 'application', 'During escrow, your buyer''s survey shows the neighbor''s garage extends three feet onto the lot. What should the agent do?', '["Tell the buyer to move the property line markers","Ask the neighbor to sign a note giving up the land","Tell the buyer it''s minor and not worth mentioning to anyone","Tell the buyer right away and recommend they get legal advice before removing contingencies"]'::jsonb, '3'::jsonb, 'This is an encroachment, which can affect title and value. Disclose it promptly and refer the buyer to an attorney or the title company.', '["Moving markers is never appropriate and could be unlawful.","Drafting legal documents to resolve title issues is legal work; the agent should refer it out.","An encroachment can affect title and value. Hiding or minimizing it breaches the agent''s duties.",""]'::jsonb, 'Survey surprise? Tell, then refer.', null, '[]'::jsonb, null, 'encroachment-agent-action', 'unverified'),
  ('N1.3-06', 'lesson', null, false, 'national', 'N1', 'N1.3', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'recall', 'Which statement about a license to use land is correct?', '["It runs with the land when the property is sold","It must be recorded to be valid","It is a type of lien","It is personal permission that can usually be revoked"]'::jsonb, '3'::jsonb, 'A license is a personal, revocable privilege. It is not an interest in the land.', '["Running with the land describes an easement appurtenant, not a license.","A license is informal permission and does not need to be recorded.","A license secures no debt, so it is not a lien.",""]'::jsonb, 'A license is a permission slip.', null, '[]'::jsonb, null, 'license-revocable', 'unverified'),
  ('N1.3-07', 'lesson', null, false, 'national', 'N1', 'N1.3', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'A parcel has no access to any road except across a neighbor''s land. A court may create:', '["A license","An easement in gross","An easement by necessity","A lis pendens"]'::jsonb, '2'::jsonb, 'An easement by necessity gives a landlocked parcel access to a road.', '["A license is revocable and would not solve a permanent access problem.","An easement in gross benefits a person or company, not a landlocked parcel.","","A lis pendens is a notice of a pending lawsuit."]'::jsonb, 'Landlocked? Necessity opens the gate.', null, '[]'::jsonb, null, 'easement-by-necessity-landlocked', 'unverified'),
  ('N1.3-08', 'lesson', null, false, 'national', 'N1', 'N1.3', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'tf', 2, 'recall', 'When the dominant parcel is sold, the benefit of an easement appurtenant transfers to the buyer.', '["True","False"]'::jsonb, '0'::jsonb, 'True. Easements appurtenant run with the land, so the benefit passes to the new owner.', '["","An easement appurtenant runs with the land and transfers automatically with either parcel."]'::jsonb, 'Appurtenant attaches to the land, not the owner.', null, '[]'::jsonb, null, 'appurtenant-runs-with-land', 'unverified'),
  ('N1.3-09', 'lesson', null, false, 'national', 'N1', 'N1.3', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'tf', 1, 'recall', 'Every encumbrance is a lien.', '["True","False"]'::jsonb, '1'::jsonb, 'False. All liens are encumbrances, but many encumbrances, like easements, are not liens.', '["Easements, deed restrictions, and encroachments are encumbrances that are not liens. Every lien is an encumbrance, but not the other way around.",""]'::jsonb, 'All liens encumber; not all encumbrances are liens.', null, '[]'::jsonb, null, 'encumbrance-vs-lien', 'unverified'),
  ('N1.3-10', 'lesson', null, false, 'national', 'N1', 'N1.3', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'order', 3, 'application', 'A property is sold at foreclosure. Put these claims in the usual order of payment, first to last.', '["Unpaid real property taxes","First mortgage recorded in 2019","Judgment lien recorded in 2021","Second mortgage recorded in 2023"]'::jsonb, '[0,1,2,3]'::jsonb, 'Property taxes come first. The remaining liens are generally paid in the order they were recorded.', '[]'::jsonb, 'Taxes take the front seat. Everyone else lines up by recording date.', null, '[]'::jsonb, null, 'lien-payment-order', 'unverified'),
  ('N1.3-11', 'lesson', null, false, 'national', 'N1', 'N1.3', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'recall', 'A recorded notice warning that a lawsuit affecting title to a property is pending is called a:', '["Lis pendens","Satisfaction","Mechanic''s lien","Writ of execution"]'::jsonb, '0'::jsonb, 'A lis pendens gives public notice that title is in dispute in a pending lawsuit.', '["","A satisfaction shows a debt has been paid off.","A mechanic''s lien secures payment for work or materials.","A writ of execution orders the sale of property to satisfy a judgment."]'::jsonb, 'Lis pendens: lawsuit pending.', null, '[]'::jsonb, null, 'lis-pendens-notice', 'unverified'),
  ('N1.4-01', 'lesson', null, false, 'national', 'N1', 'N1.4', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'Which estate gives the owner the greatest interest in real property?', '["Fee simple determinable","Estate for years","Fee simple absolute","Life estate"]'::jsonb, '2'::jsonb, 'Fee simple absolute is unlimited in duration, inheritable, and has no conditions.', '["A determinable fee can be lost if its condition is broken.","An estate for years is a leasehold, not ownership.","","A life estate ends when the measuring life ends."]'::jsonb, 'Absolute means no strings.', null, '[]'::jsonb, null, 'fee-simple-absolute-greatest', 'unverified'),
  ('N1.4-02', 'lesson', null, false, 'national', 'N1', 'N1.4', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'application', 'A deed grants land to the city "so long as the land is used as a public park." The city holds a:', '["Fee simple determinable","Life estate","Fee simple absolute","Leasehold estate"]'::jsonb, '0'::jsonb, '"So long as" language creates a fee simple determinable, which ends automatically if the use stops.', '["","A life estate is measured by a person''s life, not a use.","An absolute fee has no conditions; this one does.","A leasehold is a tenant''s interest under a lease."]'::jsonb, '"So long as" snaps back.', null, '[]'::jsonb, null, 'determinable-so-long-as', 'unverified'),
  ('N1.4-03', 'lesson', null, false, 'national', 'N1', 'N1.4', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'Maria deeds her home "to Ben for life, then to Carla." Carla is the:', '["Life tenant","Reversioner","Remainderman","Grantor"]'::jsonb, '2'::jsonb, 'A third party who receives the property when a life estate ends is the remainderman.', '["Ben is the life tenant.","A reversion would go back to Maria; Carla is a third party.","","Maria is the grantor."]'::jsonb, 'Remainder goes forward.', null, '[]'::jsonb, null, 'remainderman-third-party', 'unverified'),
  ('N1.4-04', 'lesson', null, false, 'national', 'N1', 'N1.4', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'application', 'Juan deeds a cabin "to Ana for life" and says nothing more. When Ana dies, the cabin:', '["Passes to Ana''s heirs","Passes to the state","Becomes owned by the tenants in possession","Reverts to Juan or his heirs"]'::jsonb, '3'::jsonb, 'With no remainderman named, the property reverts to the grantor or the grantor''s heirs.', '["Ana''s interest ended at her death, so there is nothing for her heirs to inherit.","The state takes property only by escheat when there are no heirs.","Tenants have no ownership claim from a life estate ending.",""]'::jsonb, 'Reversion goes back.', null, '[]'::jsonb, null, 'reversion-no-remainderman', 'unverified'),
  ('N1.4-05', 'lesson', null, false, 'national', 'N1', 'N1.4', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'recall', 'A life estate measured by the life of someone other than the life tenant is a:', '["Life estate pur autre vie","Legal life estate","Conventional life estate","Fee simple subject to condition subsequent"]'::jsonb, '0'::jsonb, 'Pur autre vie means "for the life of another."', '["","A legal life estate is created by law, not by the measuring life.","A conventional life estate is created by the owner and is usually measured by the life tenant''s own life.","That is a defeasible fee, not a life estate."]'::jsonb, 'Autre means other.', null, '[]'::jsonb, null, 'pur-autre-vie', 'unverified'),
  ('N1.4-06', 'lesson', null, false, 'national', 'N1', 'N1.4', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'application', 'Which action is a life tenant NOT allowed to take?', '["Live in the home","Rent the home to a tenant","Tear out the plumbing and let the house deteriorate","Sell the life estate interest"]'::jsonb, '2'::jsonb, 'A life tenant may not commit waste, meaning damage that harms the remainderman''s or reversioner''s future interest.', '["Living there is the core of a life estate.","A life tenant may lease the property for the length of the life estate.","","A life tenant may sell their interest, which lasts only as long as the measuring life."]'::jsonb, 'Use it, don''t ruin it.', null, '[]'::jsonb, null, 'life-tenant-waste', 'unverified'),
  ('N1.4-07', 'lesson', null, false, 'national', 'N1', 'N1.4', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'A lease runs from June 1, 2026, to May 31, 2027. This tenant holds a(n):', '["Tenancy at sufferance","Periodic tenancy","Tenancy at will","Estate for years"]'::jsonb, '3'::jsonb, 'Any lease with a definite start and end date is an estate for years, even if it is shorter than a year.', '["Sufferance applies only to a holdover without consent.","A periodic tenancy renews automatically, such as month to month.","A tenancy at will has no fixed term.",""]'::jsonb, 'Years ends itself.', null, '[]'::jsonb, null, 'estate-for-years-definite', 'unverified'),
  ('N1.4-08', 'lesson', null, false, 'national', 'N1', 'N1.4', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'A tenant stays after the lease expires without the landlord''s consent. This is a:', '["Periodic tenancy","Tenancy at will","Estate for years","Tenancy at sufferance"]'::jsonb, '3'::jsonb, 'A holdover without consent is a tenancy at sufferance.', '["A periodic tenancy requires agreement and renews by period.","A tenancy at will requires the landlord''s consent.","The estate for years already ended.",""]'::jsonb, 'Sufferance is uninvited.', null, '[]'::jsonb, null, 'tenancy-at-sufferance-holdover', 'unverified'),
  ('N1.4-09', 'lesson', null, false, 'national', 'N1', 'N1.4', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'tf', 1, 'recall', 'A leasehold estate is a type of freehold estate.', '["True","False"]'::jsonb, '1'::jsonb, 'False. Freehold estates are ownership estates. Leaseholds are non-freehold estates held by tenants.', '["Leaseholds are non-freehold estates: the tenant has possession, not ownership.",""]'::jsonb, 'Owners hold freeholds. Tenants hold leaseholds.', null, '[]'::jsonb, null, 'leasehold-not-freehold', 'unverified'),
  ('N1.4-10', 'lesson', null, false, 'national', 'N1', 'N1.4', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'tf', 2, 'application', 'A life tenant may sell the life estate, but the buyer''s interest ends when the measuring life ends.', '["True","False"]'::jsonb, '0'::jsonb, 'True. You can only sell what you own, and a life estate ends with the measuring life.', '["","The life tenant can sell only what they own, and that interest ends with the measuring life."]'::jsonb, 'You can sell your time, not more of it.', null, '[]'::jsonb, null, 'life-estate-sale-ends', 'unverified'),
  ('N1.4-11', 'lesson', null, false, 'national', 'N1', 'N1.4', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'A month-to-month rental that continues until either party gives notice is a(n):', '["Estate for years","Periodic tenancy","Life estate","Tenancy at sufferance"]'::jsonb, '1'::jsonb, 'A periodic tenancy renews automatically for successive periods until proper notice is given.', '["An estate for years has a fixed end date.","","A life estate is a freehold measured by a life.","Sufferance means the tenant stays without consent."]'::jsonb, 'Periodic repeats.', null, '[]'::jsonb, null, 'periodic-month-to-month', 'unverified'),
  ('N1.5-01', 'lesson', null, false, 'national', 'N1', 'N1.5', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'Ownership of real property by one person alone is called ownership in:', '["Partnership","Tenancy in common","Joint tenancy","Severalty"]'::jsonb, '3'::jsonb, 'Severalty means sole ownership, "severed" from anyone else.', '["A partnership is a business with two or more partners.","Tenancy in common requires two or more owners.","Joint tenancy requires two or more owners.",""]'::jsonb, 'Severalty is solo.', null, '[]'::jsonb, null, 'severalty-sole', 'unverified'),
  ('N1.5-02', 'lesson', null, false, 'national', 'N1', 'N1.5', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'The four unities required to create a joint tenancy are:', '["Purpose, interest, time, and transfer","Possession, interest, time, and title","Possession, income, taxes, and title","Price, interest, terms, and title"]'::jsonb, '1'::jsonb, 'Joint tenants must take equal interests, at the same time, by the same document, with equal right of possession.', '["Purpose and transfer are not unities.","","Income and taxes are not unities.","Price and terms are contract terms, not unities."]'::jsonb, 'PITT.', null, '[]'::jsonb, null, 'four-unities-pitt', 'unverified'),
  ('N1.5-03', 'lesson', null, false, 'national', 'N1', 'N1.5', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'A tenant in common dies with a will. Their interest:', '["Is extinguished","Passes under their will to their devisees","Passes automatically to the other co-owners","Reverts to the original seller"]'::jsonb, '1'::jsonb, 'Tenancy in common has no right of survivorship, so the interest passes by will or to heirs.', '["The interest survives the owner and passes to their estate.","","Automatic passage to co-owners is survivorship, which belongs to joint tenancy.","Reversion applies to life estates, not co-ownership."]'::jsonb, 'Common shares go to your people.', null, '[]'::jsonb, null, 'tic-passes-by-will', 'unverified'),
  ('N1.5-04', 'lesson', null, false, 'national', 'N1', 'N1.5', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'scenario', 3, 'application', 'Ana, Ben, and Cy own a lot as joint tenants. Ana sells her interest to Dee. What is the result?', '["Dee becomes a joint tenant with Ben and Cy","The sale is void without Ben''s and Cy''s consent","The whole joint tenancy becomes a tenancy in common","Dee is a tenant in common with a 1/3 share; Ben and Cy remain joint tenants as to 2/3"]'::jsonb, '3'::jsonb, 'Selling breaks the unities for that share only. The buyer becomes a tenant in common, and the remaining joint tenants keep survivorship between themselves.', '["Dee received her interest at a different time and by a different deed, so the unities are broken for her share.","A joint tenant may sell their interest without consent.","Only the transferred share loses the unities; Ben and Cy still share all four.",""]'::jsonb, 'PITT: break a unity, break the survivorship.', null, '[]'::jsonb, null, 'jt-sale-creates-tic', 'unverified'),
  ('N1.5-05', 'lesson', null, false, 'national', 'N1', 'N1.5', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'recall', 'Co-owners cannot agree on whether to sell. A court action to divide the property or order it sold is a:', '["Partition","Foreclosure","Condemnation","Quiet title action"]'::jsonb, '0'::jsonb, 'Partition lets a court divide co-owned property or order a sale and split the proceeds.', '["","Foreclosure enforces a lien after a default.","Condemnation is the government taking property by eminent domain.","Quiet title resolves competing claims to title."]'::jsonb, 'Can''t agree? Partition.', null, '[]'::jsonb, null, 'partition-coowners', 'unverified'),
  ('N1.5-06', 'lesson', null, false, 'national', 'N1', 'N1.5', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'Which form of co-ownership allows the owners to hold unequal shares?', '["Tenancy by the entirety","Severalty","Joint tenancy","Tenancy in common"]'::jsonb, '3'::jsonb, 'Tenants in common can hold unequal undivided interests, such as 60/40.', '["Tenancy by the entirety is for married couples who hold as one unit.","Severalty has only one owner.","Joint tenancy requires equal interests (unity of interest).",""]'::jsonb, 'Common shares can be uneven.', null, '[]'::jsonb, null, 'tic-unequal-shares', 'unverified'),
  ('N1.5-07', 'lesson', null, false, 'national', 'N1', 'N1.5', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'In a trust, who holds legal title to the property?', '["The trustor","The beneficiary","The county recorder","The trustee"]'::jsonb, '3'::jsonb, 'The trustee holds legal title and manages the property for the beneficiary.', '["The trustor creates the trust and transfers the property into it.","The beneficiary receives the benefits but does not hold legal title.","The recorder records documents but holds no title.",""]'::jsonb, 'Trustor sets it up. Trustee holds it. Beneficiary enjoys it.', null, '[]'::jsonb, null, 'trustee-legal-title', 'unverified'),
  ('N1.5-08', 'lesson', null, false, 'national', 'N1', 'N1.5', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'recall', 'A corporation that owns real property holds title as:', '["Joint tenants with its directors","A life tenant","Tenants in common with its shareholders","An owner in severalty"]'::jsonb, '3'::jsonb, 'A corporation is a single legal entity, so it owns property in severalty.', '["Directors manage the company but don''t own its property.","A corporation''s ownership isn''t measured by a life.","Shareholders own stock, not the real estate.",""]'::jsonb, 'One entity, one owner.', null, '[]'::jsonb, null, 'corporation-severalty', 'unverified'),
  ('N1.5-09', 'lesson', null, false, 'national', 'N1', 'N1.5', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'tf', 2, 'recall', 'A joint tenant can leave their interest to an heir by will.', '["True","False"]'::jsonb, '1'::jsonb, 'False. Survivorship controls, so the interest passes to the surviving joint tenants.', '["Right of survivorship passes the interest to the surviving joint tenants at the moment of death, before a will can act on it.",""]'::jsonb, 'Survivorship beats the will.', null, '[]'::jsonb, null, 'jt-cannot-devise', 'unverified'),
  ('N1.5-10', 'lesson', null, false, 'national', 'N1', 'N1.5', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'tf', 1, 'recall', 'In a limited partnership, limited partners generally risk only the amount they invested.', '["True","False"]'::jsonb, '0'::jsonb, 'True. Limited partners are passive investors with limited liability.', '["","Limited partners'' liability is limited to their investment; the general partner carries full liability."]'::jsonb, 'Limited partner, limited risk.', null, '[]'::jsonb, null, 'limited-partner-liability', 'unverified'),
  ('N1.5-11', 'lesson', null, false, 'national', 'N1', 'N1.5', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'recall', 'Which entity gives its owners limited personal liability and can be taxed as a pass-through entity?', '["General partnership","Limited liability company","Sole proprietorship","Joint tenancy"]'::jsonb, '1'::jsonb, 'An LLC combines limited liability with flexible, often pass-through, taxation.', '["General partners are personally liable for partnership debts.","","A sole proprietor is personally liable for all business debts.","Joint tenancy is a form of co-ownership, not a business entity."]'::jsonb, 'LLC: limited liability, less corporate double tax.', null, '[]'::jsonb, null, 'llc-liability-taxation', 'unverified'),
  ('N1.6-01', 'lesson', null, false, 'national', 'N1', 'N1.6', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'A condominium owner owns:', '["The unit in fee simple plus an undivided interest in the common elements","A right to use the unit one week each year","Shares in a corporation plus a proprietary lease","Only the interior paint and fixtures"]'::jsonb, '0'::jsonb, 'Condo ownership is fee title to the unit plus a shared undivided interest in the common elements.', '["","A recurring week describes a timeshare.","Shares and a proprietary lease describe a cooperative.","Condo owners own the unit itself, not just its finishes."]'::jsonb, 'Condo: own the box, share the rest.', null, '[]'::jsonb, null, 'condo-ownership-structure', 'unverified'),
  ('N1.6-02', 'lesson', null, false, 'national', 'N1', 'N1.6', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'A buyer purchasing in a cooperative receives:', '["An easement in gross","Shares in the corporation and a proprietary lease","A timeshare estate","A deed to the unit"]'::jsonb, '1'::jsonb, 'In a co-op, the corporation owns the building. Buyers get shares and a proprietary lease.', '["An easement in gross benefits a person or company; it isn''t co-op ownership.","","A timeshare estate is ownership of a time interval.","Co-op buyers don''t get a deed; the corporation owns the building."]'::jsonb, 'Co-op: you own stock, not a unit.', null, '[]'::jsonb, null, 'coop-shares-lease', 'unverified'),
  ('N1.6-03', 'lesson', null, false, 'national', 'N1', 'N1.6', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'recall', 'A balcony that only one condo unit can use is an example of a:', '["Limited common element","General common element","Trade fixture","Separate unit"]'::jsonb, '0'::jsonb, 'Limited common elements are owned in common but reserved for the use of one or some units.', '["","General common elements, like the lobby, are for all owners.","Trade fixtures are a commercial tenant''s equipment.","The balcony is not part of the unit itself in most declarations; it is reserved for it."]'::jsonb, 'Limited: shared ownership, private use.', null, '[]'::jsonb, null, 'limited-common-element-balcony', 'unverified'),
  ('N1.6-04', 'lesson', null, false, 'national', 'N1', 'N1.6', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'recall', 'A condominium is legally created when the developer records a:', '["Declaration (master deed)","Proprietary lease","Lis pendens","Bill of sale"]'::jsonb, '0'::jsonb, 'Recording the declaration creates the condominium and its common elements.', '["","A proprietary lease belongs to cooperatives.","A lis pendens is notice of a lawsuit.","A bill of sale transfers personal property."]'::jsonb, 'Declare it to create it.', null, '[]'::jsonb, null, 'condo-declaration-creates', 'unverified'),
  ('N1.6-05', 'lesson', null, false, 'national', 'N1', 'N1.6', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 1, 'recall', 'In a planned unit development (PUD), owners typically own:', '["Only the airspace inside their unit","Their lot and home, while the association owns the common areas","A right to use a unit for a set week","Shares in a corporation"]'::jsonb, '1'::jsonb, 'PUD owners hold title to their lot and home. The association owns and maintains the common areas.', '["Airspace ownership describes a condominium unit.","","A set week describes a timeshare.","Shares describe a cooperative."]'::jsonb, 'PUD: your dirt, their park.', null, '[]'::jsonb, null, 'pud-ownership', 'unverified'),
  ('N1.6-06', 'lesson', null, false, 'national', 'N1', 'N1.6', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 3, 'application', 'Which risk is greater for a cooperative owner than for a condominium owner?', '["The owner cannot get a separate tax bill for the common areas","The owner must pay HOA assessments","Other shareholders'' failure to pay can leave the remaining owners covering the blanket mortgage","The owner cannot sell their interest"]'::jsonb, '2'::jsonb, 'A co-op usually has one blanket mortgage and shared expenses. When some owners default, the rest may have to cover the shortfall.', '["Condo owners don''t get separate tax bills for common areas either; this isn''t a co-op specific risk.","Both condo and co-op owners pay association charges.","","Co-op shares can be sold, often with board approval."]'::jsonb, 'Co-op: one loan, everyone''s problem.', null, '[]'::jsonb, null, 'coop-blanket-mortgage-risk', 'unverified'),
  ('N1.6-07', 'lesson', null, false, 'national', 'N1', 'N1.6', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'recall', 'What is the key difference between a timeshare estate and a timeshare use?', '["There is no legal difference","A timeshare estate is a real property ownership interest; a timeshare use is only a right to use","Only a timeshare use can be sold","A timeshare use is always permanent; an estate expires"]'::jsonb, '1'::jsonb, 'A timeshare estate conveys a real property interest. A timeshare use gives only the right to occupy for a period.', '["The difference matters: one is ownership, the other is a right of use.","","Timeshare estates can be sold like other real property interests.","A timeshare use typically lasts for a set number of years; it is the estate that is an ownership interest."]'::jsonb, 'A timeshare estate owns a slice of time. A timeshare use rents it.', null, '[]'::jsonb, null, 'timeshare-estate-vs-use', 'unverified'),
  ('N1.6-08', 'lesson', null, false, 'national', 'N1', 'N1.6', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'scenario', 2, 'application', 'A buyer asks whether the condo association is planning a special assessment. What should the agent do?', '["Tell the buyer it doesn''t matter because assessments are tax deductible","Assure the buyer there won''t be one","Tell the buyer special assessments only apply to commercial buildings","Help the buyer get and review the association documents, including the budget, reserves and meeting minutes, and direct the question to the association"]'::jsonb, '3'::jsonb, 'The facts are in the association''s documents. Help the buyer get them and avoid guessing.', '["Homeowner assessments on a personal residence are generally not deductible, and the question still deserves a real answer.","Guessing about future assessments could be a misrepresentation.","Residential associations can levy special assessments.",""]'::jsonb, 'Don''t guess. Get the documents.', null, '[]'::jsonb, null, 'condo-special-assessment-agent', 'unverified'),
  ('N1.6-09', 'lesson', null, false, 'national', 'N1', 'N1.6', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'tf', 1, 'recall', 'Each condominium unit is taxed separately.', '["True","False"]'::jsonb, '0'::jsonb, 'True. Each unit is a separate parcel with its own tax assessment.', '["","Each condo unit is a separate parcel with its own tax bill, which includes its share of the common elements."]'::jsonb, 'Own the box, own the bill.', null, '[]'::jsonb, null, 'condo-taxed-separately', 'unverified'),
  ('N1.6-10', 'lesson', null, false, 'national', 'N1', 'N1.6', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'tf', 1, 'recall', 'In a cooperative, each resident typically receives a deed to their apartment.', '["True","False"]'::jsonb, '1'::jsonb, 'False. The corporation owns the building; residents hold shares and a proprietary lease.', '["Co-op residents own shares in the corporation and hold a proprietary lease; the corporation holds the deed.",""]'::jsonb, 'Co-op: stock, not a deed.', null, '[]'::jsonb, null, 'coop-no-deed', 'unverified'),
  ('N1.6-11', 'lesson', null, false, 'national', 'N1', 'N1.6', 'Content Outlines 01/15/2025 (#092901) [verify]', 'PRIN', 'mcq', 2, 'application', 'A condo owner stops paying association assessments. What can the association generally do?', '["Take ownership of the unit without any process","Evict the owner like a tenant","Place a lien on the owner''s unit","Nothing, because assessments are voluntary"]'::jsonb, '2'::jsonb, 'Unpaid assessments can become a lien on the unit, which the association may enforce.', '["Ownership can''t be taken without legal process.","An owner isn''t a tenant, so eviction doesn''t apply.","","Assessments are mandatory under the declaration."]'::jsonb, 'Skip the dues, risk a lien.', null, '[]'::jsonb, null, 'hoa-assessment-lien', 'unverified'),
  ('N10.1-01', 'lesson', null, false, 'national', 'N10', 'N10.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'LAW', 'mcq', 1, 'recall', 'A broker deposits a buyer''s earnest money into the brokerage''s operating account. This is:', '["Escrow","Conversion","Commingling","Reconciliation"]'::jsonb, '2'::jsonb, 'Mixing client funds with the broker''s own money is commingling.', '["Escrow is the proper holding of funds, not mixing them.","Conversion is using the money for oneself; mixing comes first.","","Reconciliation is matching records to the bank."]'::jsonb, 'Their money, separate account.', null, '[]'::jsonb, null, 'commingling-definition', 'unverified'),
  ('N10.1-02', 'lesson', null, false, 'national', 'N10', 'N10.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'LAW', 'mcq', 1, 'recall', 'A broker uses a tenant''s security deposit to pay office rent. This is:', '["A reasonable accommodation","Commingling only","Conversion","Allowed if repaid within 30 days"]'::jsonb, '2'::jsonb, 'Using trust funds for personal or business purposes is conversion, a form of theft.', '["That''s a fair housing concept.","Spending the money goes beyond mixing it.","","Repayment doesn''t excuse the misuse."]'::jsonb, 'Spend it and it''s stolen.', null, '[]'::jsonb, null, 'conversion-definition', 'unverified'),
  ('N10.1-03', 'lesson', null, false, 'national', 'N10', 'N10.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'LAW', 'mcq', 2, 'recall', 'Who is ultimately responsible for a brokerage''s trust account?', '["The broker","The salesperson who received the money","The bank","The bookkeeper"]'::jsonb, '0'::jsonb, 'The broker is legally responsible for trust funds, even when others handle them.', '["","Salespeople turn funds over to the broker.","The bank holds the deposit but isn''t responsible for the records.","Staff may help, but the broker answers for the account."]'::jsonb, 'The broker answers for the account.', null, '[]'::jsonb, null, 'broker-responsible-trust', 'unverified'),
  ('N10.1-04', 'lesson', null, false, 'national', 'N10', 'N10.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'LAW', 'mcq', 2, 'application', 'A deal falls apart and both buyer and seller demand the earnest money the broker holds. The broker should:', '["Hold the funds until the parties agree in writing or a court or legal process directs release","Split it 50/50","Keep it as a fee","Give it to the seller, the broker''s client"]'::jsonb, '0'::jsonb, 'Disputed trust funds stay put until the parties agree or a lawful process decides.', '["","The broker has no authority to split disputed funds.","Keeping it is conversion.","The broker can''t decide a disputed claim for one side."]'::jsonb, 'Disputed money doesn''t move on your say-so.', null, '[]'::jsonb, null, 'disputed-earnest-hold', 'unverified'),
