  ('N10.1-10', 'lesson', null, false, 'national', 'N10', 'N10.1', 'Content Outlines 01/15/2025 (#092901) [verify]', 'LAW', 'number', 2, 'calculation', 'A broker''s records show $48,250 owed to clients, but the trust bank balance is $46,900. How much is the shortage?', '[]'::jsonb, '{"value":1350,"tolerance":0,"unit":"dollars"}'::jsonb, 'The account is short $1,350, which the broker must find and correct.', '[]'::jsonb, 'Every dollar has a name.', 'Shortage = amount owed to clients − bank balance', '["$48,250 − $46,900 = $1,350."]'::jsonb, null, 'trust-shortage-calc', 'unverified'),
