  ('N10.5-07', 'lesson', null, false, 'national', 'N10', 'N10.5', 'Content Outlines 01/15/2025 (#092901) [verify]', 'LAW', 'tf', 2, 'recall', 'An unlicensed assistant may negotiate price with buyers if the agent is busy.', '["True","False"]'::jsonb, '1'::jsonb, 'False.', '["Negotiating is licensed activity. Unlicensed assistants are limited to clerical and administrative tasks.",""]'::jsonb, 'No license, no negotiating.', null, '[]'::jsonb, null, 'unlicensed-assistant-limits', 'unverified'),
